function stepping_up_tower(r0, k0, N0, h):
    r <- r0; k <- k0; logN <- log2(N0)
    trace <- [(r, k, logN)]
    for i from 1 to h:
        logN <- 2 ^ logN      # N -> 2^N
        r <- r + 1
        k <- k + 1
        append (r, k, logN) to trace
    return trace   # final ground set size = tower(h, N0)

function tower(h, N, cap):
    v <- N
    for i from 1 to h:
        if v > cap:
            return SYMBOLIC("2^" repeated)   # too large to represent
        v <- 2 ^ v
    return v

